begin;
select plan(15);
select has_function('public','transition_game_lifecycle',array['text','text','text','uuid'],'lifecycle command remains available');
select ok((select prosecdef from pg_proc where oid='private.transition_game_lifecycle_impl(text,text,text,uuid)'::regprocedure),'lifecycle implementation remains definer');
insert into auth.users(id,aud,role,email,is_anonymous) values
 ('00000000-0000-0000-0000-000000000801','authenticated','authenticated','completion-staff@example.test',false);
insert into public.staff_members(id,auth_user_id,display_name,active) values
 ('40000000-0000-0000-0000-000000000801','00000000-0000-0000-0000-000000000801','Completion Staff',true);
reset role;
update public.games set lifecycle='live', narrative_phase='lobby' where code='TEST01';
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000801',true);
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000801","role":"authenticated","is_anonymous":false}',true);
select throws_ok($$select * from public.transition_game_lifecycle('TEST01','live','completed','80000000-0000-0000-0000-000000000801')$$,'P0001','GAME_NOT_READY_TO_COMPLETE','lobby cannot complete');
reset role; update public.games set narrative_phase='role_reveal' where code='TEST01'; set local role authenticated;
select throws_ok($$select * from public.transition_game_lifecycle('TEST01','live','completed','80000000-0000-0000-0000-000000000802')$$,'P0001','GAME_NOT_READY_TO_COMPLETE','role reveal cannot complete');
reset role; update public.games set narrative_phase='briefing' where code='TEST01'; set local role authenticated;
select throws_ok($$select * from public.transition_game_lifecycle('TEST01','live','completed','80000000-0000-0000-0000-000000000803')$$,'P0001','GAME_NOT_READY_TO_COMPLETE','briefing cannot complete');
reset role; update public.games set narrative_phase='discovery' where code='TEST01'; set local role authenticated;
select throws_ok($$select * from public.transition_game_lifecycle('TEST01','live','completed','80000000-0000-0000-0000-000000000804')$$,'P0001','GAME_NOT_READY_TO_COMPLETE','discovery cannot complete');
reset role; update public.games set narrative_phase='comparison' where code='TEST01'; set local role authenticated;
select throws_ok($$select * from public.transition_game_lifecycle('TEST01','live','completed','80000000-0000-0000-0000-000000000805')$$,'P0001','GAME_NOT_READY_TO_COMPLETE','comparison cannot complete');
reset role; update public.games set narrative_phase='pressure' where code='TEST01'; set local role authenticated;
select throws_ok($$select * from public.transition_game_lifecycle('TEST01','live','completed','80000000-0000-0000-0000-000000000806')$$,'P0001','GAME_NOT_READY_TO_COMPLETE','pressure cannot complete');
reset role; update public.games set narrative_phase='deliberation' where code='TEST01'; set local role authenticated;
select throws_ok($$select * from public.transition_game_lifecycle('TEST01','live','completed','80000000-0000-0000-0000-000000000808')$$,'P0001','GAME_NOT_READY_TO_COMPLETE','deliberation cannot complete');
reset role; update public.games set narrative_phase='final_vote' where code='TEST01'; set local role authenticated;
select throws_ok($$select * from public.transition_game_lifecycle('TEST01','live','completed','80000000-0000-0000-0000-000000000809')$$,'P0001','GAME_NOT_READY_TO_COMPLETE','final vote cannot complete');
reset role; update public.games set narrative_phase='reveal' where code='TEST01'; set local role authenticated;
select is((select lifecycle from public.transition_game_lifecycle('TEST01','live','completed','80000000-0000-0000-0000-000000000810')),'completed','reveal can complete');
reset role;
select is((select lifecycle from public.games where code='TEST01'),'completed','completion is authoritative');
set local role authenticated;
select throws_ok($$select * from public.transition_game_lifecycle('TEST01','completed','live','80000000-0000-0000-0000-000000000812')$$,'P0001','INVALID_TRANSITION','completed remains terminal');
reset role;
insert into public.events(id,name) values('e0000000-0000-0000-0000-000000000801','Abort event');
insert into public.games(id,event_id,code,lifecycle,narrative_phase) values('a0000000-0000-0000-0000-000000000801','e0000000-0000-0000-0000-000000000801','ABORT-TEST','live','lobby');
set local role authenticated;
select is((select lifecycle from public.transition_game_lifecycle('ABORT-TEST','live','aborted','80000000-0000-0000-0000-000000000811')),'aborted','abort remains available before reveal');
reset role;
select is((select lifecycle from public.games where code='ABORT-TEST'),'aborted','abort behavior unchanged');
select * from finish();
rollback;
